import { IErrorState, INicknameConfig, INicknameState, INicknameStateConfig, IRequirementsState } from '../types';

export class NicknameState implements INicknameState {

    public config: INicknameStateConfig;
    public requirements: IRequirementsState = {
        length: false,
        startingCharacter: false,
        alphaNumeric: false
    };
    public nickname: string = '';
    public isSubmitting: boolean = false;
    public nicknameAccepted: boolean = false;
    public error: IErrorState = {
        hasErrored: false,
        errorCode: 0,
        errors: []
    };

    constructor(config: INicknameConfig) {
        // setting optional and split properties
        config.maxCharacters = config.maxCharacters || 20;
        config.minCharacters = config.minCharacters || 6;
        config.userId = typeof(config.userId) === 'number' ? config.userId.toString() : config.userId;
        config.cMIdentifier = config.cMIdentifier || 'CM';
        this.config = config as INicknameStateConfig;
    }

    public resetErrorState(): void {
        this.error.hasErrored = false;
        this.error.errorCode = 0;
        this.error.errors.length = 0;
    }

}